    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Defina as configurações de todo o sistema: URL base, segurança, idioma padrão, fuso horário, padrões de pontuação de risco e muito mais.',
    'SettingsPreferencesDesc'             => 'Valores padrão e preferências de comportamento no SimpleRisk: idioma, fuso horário, status de auditoria, requisitos de mapeamento de risco, opções de ativação/desativação do comportamento da interface do usuário e similares.',
    'SettingsFileUploadDesc'              => 'Tipos de arquivos permitidos para upload e limites de tamanho para os diversos campos de anexos.',
    'SettingsMailDesc'                    => 'Configuração de SMTP para notificações por e-mail de saída, incluindo transporte, host, autenticação e endereço de resposta.',
    'SettingsBackupsDesc'                 => 'Configure a retenção de backups, o agendamento e os links de download para backups do banco de dados SimpleRisk.',
    'SettingsSecurityDesc'                => 'Configurações de autenticação, sessão, política de senhas, URL base e segurança da API.',
    'SettingsLoggingDesc'                 => 'Configuração de registro de depuração e auditoria: níveis de registro, retenção e localização dos arquivos de registro.',
    'HealthCheckDesc'                     => 'Diagnostique o status do sistema: versão do PHP, extensões, permissões de arquivo, conectividade do banco de dados, agendamento do cron e ativações de Extras.',
    'AnnouncementsDesc'                   => 'Crie e gerencie banners de anúncios visíveis para todos os usuários.',
    'RegisterAndUpgradeDesc'              => 'Registre sua instalação do SimpleRisk, insira ou renove uma chave de assinatura e acione atualizações Core/Extra com um clique.',
    'QueueMonitorDesc'                    => 'Inspecione a fila de tarefas em segundo plano: tarefas pendentes, em andamento e com falha.',
    'ExtrasDesc'                          => 'Ative, desative e configure os Extras do SimpleRisk (complementos pagos).',
    'ArtificialIntelligenceExtraDesc'     => 'O Extra de Inteligência Artificial oferece análise de riscos aprimorada (incluindo avaliações FAIR) e documentação personalizada.',
    'CustomizationExtraDesc'              => 'O Extra de Personalização permite adicionar e remover diferentes tipos de campos e criar dinamicamente modelos de página personalizados.',
    'NotificationExtraDesc'               => 'O Extra de Notificação por E-mail permite que o SimpleRisk envie notificações por e-mail quando riscos forem enviados, modificados ou tratados de alguma outra forma. Este Extra também pode ser adicionado como um script agendado para enviar lembretes periódicos quando os riscos estiverem prontos para uma revisão de gestão. No produto SimpleRisk Core, sem este Extra, nenhuma notificação é comunicada fora da própria ferramenta.',
    'VulnerabilityManagementExtraDesc'    => 'O Extra de Gestão de Vulnerabilidades oferece aos clientes a capacidade de integrar sua instância do SimpleRisk com Qualys, Tenable.io ou Rapid7 Nexpose/InsightVM e importar para o SimpleRisk tanto dados de ativos quanto de vulnerabilidades. A partir daí, você pode selecionar quais sites deseja cobrir, determinar quais pontuações de vulnerabilidade devem ser importadas e fazer a triagem de quais vulnerabilidades serão transformadas em riscos para acompanhá-las.',
    'IncidentManagementExtraDesc'         => 'O Extra de Gestão de Incidentes é baseado no Computer Security Incident Handling Guide do NIST 800-61 e oferece recursos de gestão de incidentes dentro do sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Renomeie a terminologia do SimpleRisk (Risco, Ativo, Estrutura, etc.) em toda a interface do usuário.',
    'RiskConfigurationDesc'               => 'Configure as regras de pontuação de risco: níveis, apetite, limites de SLA e as fórmulas de risco clássica e contribuinte.',
    'RiskAndThreatCatalogDesc'            => 'Mantenha o catálogo de valores de risco e ameaça usados nas listas suspensas.',
    'AddAndRemoveValuesDesc'              => 'Gerencie os valores das listas suspensas para os campos de risco: localização, origem, categoria, equipe, tecnologia e muito mais.',
    'AssetValuationDesc'                  => 'Configure a escala de valoração de ativos e as substituições de valoração por ativo.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Adicionar, editar, desativar e redefinir usuários; gerenciar política de senhas.',
    'RoleManagementDesc'                  => 'Defina as funções e as permissões que cada função concede.',
    'TeamManagementDesc'                  => 'Criar e gerenciar equipes usadas para filtragem de visibilidade de registros.',
    'SeparationExtraDesc'                 => 'O Extra de Separação Baseada em Equipes restringe a visualização de riscos apenas aos usuários que são membros da equipe à qual o risco está atribuído. No produto SimpleRisk Core, sem este Extra, todo usuário pode ver todos os riscos.',
    'CustomAuthenticationExtraDesc'       => 'O Extra de Autenticação Personalizada oferece suporte à autenticação por Active Directory e SAML. No produto SimpleRisk Core, sem este Extra, a única opção é criar novos usuários no repositório de identidades do SimpleRisk.',
    'EncryptionExtraDesc'                 => 'O recurso Banco de Dados Criptografado Extra gera uma chave de criptografia AES-256 bits aleatória e a utiliza para criptografar textos confidenciais antes de serem inseridos no banco de dados SimpleRisk. Isso impede que qualquer pessoa visualize ou modifique os dados sem usar o aplicativo SimpleRisk diretamente.',
    'OrganizationManagementDesc'          => 'O Extra de Hierarquia Organizacional permite definir várias Unidades de Negócios, que podem incluir qualquer número de equipes. Os usuários podem então ser atribuídos a uma ou mais equipes de diversas Unidades de Negócios. Isso afeta a capacidade do usuário de ver e usar as equipes, os usuários e os ativos aos quais não está associado.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Exclua riscos em massa. Use com moderação — as exclusões são permanentes.',
    'AuditTrailDesc'                      => 'Pesquise e exporte o registro de auditoria do sistema com as ações dos usuários.',
    'ImportExportExtraDesc'               => 'O Extra de Importação e Exportação oferece a capacidade de importar dados para o SimpleRisk mapeando campos de um arquivo CSV para campos do banco de dados do SimpleRisk. Ele pode ser usado para importar resultados de auditoria de uma planilha de terceiros, resultados de varreduras de vulnerabilidades de outra ferramenta, ativos da sua CMDB e mais. O Extra também permite exportar do SimpleRisk arquivos CSV contendo Riscos, Mitigações, Revisões ou um relatório Combinado dos três.',
    'JiraExtraDesc'                       => 'O Extra de Integração com o Jira oferece aos usuários a capacidade de integrar de forma bidirecional com uma instância do Jira. Ele permite conectar riscos a Problemas do Jira, além de sincronizar seus dados, status e comentários.',
    'APIExtraDesc'                        => 'O Extra de API permite que os clientes usem uma API RESTful para criar interações automatizadas por script com outros aplicativos, obtendo automação avançada e aproveitando a infraestrutura existente.',
    'AdvancedSearchExtraDesc'             => 'O Extra de Pesquisa Avançada transforma a caixa de pesquisa da barra superior em uma única pesquisa abrangendo riscos, estruturas, controles, documentos, exceções, testes, auditorias, ativos e grupos de ativos, com uma página de Pesquisa completa para analisar os resultados. Ele mostra apenas os registros que o usuário tem permissão para ver.',
    'AssessmentsExtraDesc'                => 'O Extra de Avaliação de Riscos oferece aos usuários a capacidade de definir contatos, criar perguntas (incluindo lógica), reunir várias perguntas em um modelo de questionário, criar questionários e enviá-los aos contatos, ver os resultados dos questionários, adicionar riscos com base nesses resultados, comparar os resultados ao longo do tempo, importar e exportar avaliações personalizadas externamente e revisar a trilha de auditoria da avaliação de riscos.',
    'ActiveAssessmentsDesc'               => 'Veja e gerencie as avaliações atualmente em andamento.',
    'WorkflowsExtraDesc'                  => 'O Extra de Fluxos de Trabalho oferece um mecanismo visual de fluxos de trabalho orientado a eventos que automatiza ações de gestão de riscos em resposta a eventos dentro do SimpleRisk. Você pode projetar fluxos de trabalho acionados por alterações — como um risco sendo enviado, atualizado ou revisado — para encaminhar aprovações, atribuir tarefas e manter seu processo em andamento sem intervenção manual.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "O Secure Controls Framework (SCF) Extra é uma integração direta entre o Secure Controls Framework e o SimpleRisk. Ele importa o catálogo de controles do SCF e seus mapeamentos em uma ampla gama de estruturas de conformidade e cibersegurança para a funcionalidade de Governança do SimpleRisk, permitindo que você adote as estruturas de que precisa e gerencie seus controles sem precisar criá-los manualmente.",

    // Configure Hub - tile descriptions (maintenance category)
