    'EnableCSPHelp' => 'A Política de Segurança de Conteúdo (CSP) restringe o navegador a carregar scripts, estilos, imagens e fontes somente do próprio SimpleRisk e bloqueia o enquadramento de páginas e envios de formulários entre origens. É a defesa nativa mais forte contra cross-site scripting. Mantenha ativada, a menos que entre em conflito com um proxy, uma extensão de navegador ou uma integração de terceiros em seu ambiente.',
