    'AssetScoring' => 'Pontuação de Ativos',
    'AssetScoringSettingsHint' => 'Cada ativo é classificado como Baixo, Moderado ou Alto quanto a confidencialidade, integridade e disponibilidade, e a confidencialidade pode, alternativamente, ser Não aplicável, o que a exclui dos dois resultados. Sua categorização FIPS é a mais alta das três classificações. Sua pontuação ponderada é a média ponderada dos três valores de nível, e os limites das faixas transformam essa pontuação em uma faixa Baixa, Moderada ou Alta. Alterar estas configurações recalcula imediatamente a pontuação de todos os ativos.',
    'Weights' => 'Pesos',
    'AssetScoringWeightsHint' => 'Quanto cada objetivo conta na pontuação ponderada: de 0 a 100, com até duas casas decimais. Um peso 0 exclui esse objetivo. Integridade e Disponibilidade não podem ser ambas 0, porque uma confidencialidade Não aplicável é sempre excluída.',
    'LevelValues' => 'Valores de nível',
    'AssetScoringLevelValuesHint' => 'O número que cada classificação contribui para a pontuação ponderada: acima de 0 e até 100, com até duas casas decimais, sendo Baixo menor que Moderado e Moderado menor que Alto. Os valores padrão são Baixo 1, Moderado 2 e Alto 3.',
    'BandThresholds' => 'Limites das faixas',
    'AssetScoringBandThresholdsHint' => 'Uma pontuação ponderada igual ou superior a um determinado limite é classificada nessa faixa, e uma pontuação abaixo do limite Moderado é considerada Baixa. A faixa Moderada deve começar acima do valor Baixo, e a faixa Alta deve começar acima da faixa Moderada e não ultrapassar o valor Alto.',
    'ModerateStartsAt' => 'Moderado começa em',
    'HighStartsAt' => 'Alto começa em',
    'DefaultScoringForNewAssets' => 'Pontuação padrão para novos ativos',
    'AssetScoringDefaultsHint' => 'Essas classificações são pré-selecionadas quando alguém adiciona um ativo no formulário de ativos. Os ativos criados por meio de descoberta, importação ou API permanecem sem classificação, a menos que forneçam suas próprias classificações. Deixe todas as três opções como "Não definido" para desativar essa função.',
    'AssetScoringWeightsInvalid' => 'Os pesos de pontuação de ativos devem ser números de 0 a 100 com no máximo duas casas decimais, e Integridade e Disponibilidade não podem ser ambas iguais a 0.',
    'AssetScoringValuesInvalid' => 'Os valores de nível da Pontuação de ativos devem ser números acima de 0 e até 100 com no máximo duas casas decimais, sendo Baixo menor que Moderado e Moderado menor que Alto.',
    'AssetScoringThresholdsInvalid' => 'Os limites das faixas de pontuação de ativos devem ter no máximo duas casas decimais, com a faixa Moderada começando acima do valor Baixo, a faixa Alta começando acima da faixa Moderada e a faixa Alta não podendo ultrapassar o valor Alto.',
