    'AssetScoringResultHelpLabel' => 'Explicação de {$result}',
    'AssetScoringScoreHelp' => 'A pontuação ponderada combina as três classificações em um único número de {$low} a {$high}. Cada classificação se torna seu valor definido, e cada um é multiplicado pelo peso do respectivo objetivo. Os resultados são somados e divididos pelo total dos pesos. Uma Confidencialidade Não aplicável é deixada de fora, junto com seu peso. Os valores definidos e os pesos são configurados em Preferências. Os três objetivos devem ser classificados antes de uma pontuação ser exibida.',
    'AssetScoringCategorizationHelp' => 'A categorização de segurança FIPS 199 é o valor máximo (high-water mark): a classificação mais alta entre os objetivos aplicáveis. Uma única classificação Alta torna o ativo Alto, independentemente das demais. Não aplicável é ignorado.',
